def minimumSwap(s1: str, s2: str) -> int:
    # Count mismatches
    mismatch_x1 = 0
    mismatch_y1 = 0

    for c1, c2 in zip(s1, s2):
        if c1 != c2:
            if c1 == 'x':
                mismatch_x1 += 1
            else:
                mismatch_y1 += 1

    # If the total number of mismatches is odd, it's impossible to make the strings equal
    if (mismatch_x1 + mismatch_y1) % 2 != 0:
        return -1

    # Calculate the minimum number of swaps
    swaps = mismatch_x1 // 2 + mismatch_y1 // 2
    if mismatch_x1 % 2 == 1:
        swaps += 2

    return swaps
